3	import java.time.LocalDate;
4	import java.util.Locale;
5	import java.util.Set;
6	
7	/**
8	 * The owner's unified member id, formatted {@code <REGION><FY><HASH8><CHK>}: the region code
9	 * derived from the postcode, the two-digit fiscal year of the registration date (see
10	 * {@link FiscalYears}), the first eight upper-case hex characters of the SHA-256 digest over the
11	 * owner's normalized telephone followed by their last name, and finally a single Luhn check digit
12	 * computed over the digits of the preceding {@code <REGION><FY><HASH8>}. Every value read back
13	 * from the identity (locality, fiscal year) parses it through here, so the format lives in one
14	 * place.
15	 */
16	public final class MemberId {
17	
18	    /** Number of leading hex characters of the digest kept as the identity's hash component. */
19	    private static final int HASH_LENGTH = 8;
20	
21	    /** Number of digits carried by the fiscal-year segment. */
22	    private static final int FY_LENGTH = 2;
23	
24	    /** Separator introducing the {@code -<n>} suffix a collision appends. */
25	    private static final char SEPARATOR = '-';
26	
27	    private MemberId() {
28	    }
29	
30	    /**
31	     * Build the member id {@code <REGION><FY><HASH8><CHK>} for an owner in {@code region}, whose
32	     * fiscal year is taken from {@code registrationDate} and whose normalized telephone and last
33	     * name hash to {@code HASH8}. {@code CHK} is the Luhn check digit over the digits of the
34	     * preceding segments.
35	     */
36	    public static String of(String region, LocalDate registrationDate, String normalizedTelephone,
37	            String lastName) {
38	        String fy = FiscalYears.yearOfCentury(registrationDate);
39	        String hash8 = Sha256.hex(normalizedTelephone + lastName)
40	                .substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
41	        String base = region + fy + hash8;
42	        return base + Luhn.checkDigit(base);
43	    }
44	
45	    /**
46	     * De-duplicate {@code memberId} against the ids already {@code taken}. When it is free the id
47	     * is returned unchanged; otherwise {@code -<n>} is appended with the smallest {@code n} of 2
48	     * or more that yields an id no owner already holds.
49	     */
50	    public static String deduplicate(String memberId, Set<String> taken) {
51	        if (!taken.contains(memberId)) {
52	            return memberId;
53	        }
54	        for (int n = 2; ; n++) {
55	            String candidate = memberId + SEPARATOR + n;
56	            if (!taken.contains(candidate)) {
57	                return candidate;
58	            }
59	        }
60	    }
61	
62	    /**
63	     * The region component of {@code memberId} (its identity locality) — the leading run of
64	     * letters before the fiscal-year digits — or {@link CityRegions#UNKNOWN} when the id is
65	     * absent or carries no region.
66	     */
67	    public static String regionOf(String memberId) {
68	        int end = regionLength(memberId);
69	        return end == 0 ? CityRegions.UNKNOWN : memberId.substring(0, end);
70	    }
71	
72	    /**
73	     * The fiscal-year label {@code FY<YY>} for {@code memberId}, read from its two-digit fiscal-year
74	     * segment, or null when the id is absent or carries no fiscal year.
75	     */
76	    public static String fiscalYearLabel(String memberId) {
77	        int start = regionLength(memberId);
78	        if (memberId == null || memberId.length() < start + FY_LENGTH) {
79	            return null;
80	        }
81	        return FiscalYears.labelFor(memberId.substring(start, start + FY_LENGTH));
82	    }
83	
84	    /** The length of {@code memberId}'s leading region (letters before the fiscal-year digits). */
85	    private static int regionLength(String memberId) {
86	        if (memberId == null) {
87	            return 0;
88	        }
89	        int i = 0;
90	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
91	            i++;
92	        }
93	        return i;
94	    }
95	}
