2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Fiscal-year arithmetic for date-derived owner values. The fiscal year starts on 1 July, so a
8	 * date on or after 1 July belongs to the fiscal year that begins in its own calendar year, while
9	 * a date before 1 July belongs to the fiscal year that began in the previous calendar year. A
10	 * fiscal year is identified by the calendar year in which it begins and labelled 'FY&lt;YY&gt;',
11	 * where YY is the last two digits of that starting year (e.g. any date from 2026-07-01 to
12	 * 2027-06-30 is 'FY26').
13	 */
14	public final class FiscalYears {
15	
16	    /** The month in which the fiscal year starts (1 July). */
17	    private static final Month FISCAL_YEAR_START = Month.JULY;
18	
19	    private FiscalYears() {
20	    }
21	
22	    /**
23	     * The calendar year in which {@code date}'s fiscal year begins: the date's own year from 1 July
24	     * onward, otherwise the previous year.
25	     */
26	    public static int startYear(LocalDate date) {
27	        int year = date.getYear();
28	        return date.getMonth().getValue() >= FISCAL_YEAR_START.getValue() ? year : year - 1;
29	    }
30	
31	    /**
32	     * The two-digit fiscal-year segment 'YY' for {@code date}: the last two digits of the calendar
33	     * year in which its fiscal year begins.
34	     */
35	    public static String yearOfCentury(LocalDate date) {
36	        return String.format("%02d", startYear(date) % 100);
37	    }
38	
39	    /** Label a two-digit fiscal-year segment 'YY' as 'FY&lt;YY&gt;'. */
40	    public static String labelFor(String yearOfCentury) {
41	        return "FY" + yearOfCentury;
42	    }
43	
44	    /**
45	     * The number of fiscal years elapsed between {@code from} and {@code to}, i.e. the count of
46	     * 1 July boundaries crossed. Zero when both dates fall in the same fiscal year.
47	     */
48	    public static int elapsedBetween(LocalDate from, LocalDate to) {
49	        return startYear(to) - startYear(from);
50	    }
51	}
