5	/**
6	 * Standard American Soundex encoding of a name: its first letter followed by three digits that
7	 * phonetically classify the remaining consonants, so names that sound alike share a code
8	 * (e.g. {@code Robert} and {@code Rupert} both encode to {@code R163}). Used to group owners by
9	 * how their last name sounds, both as the last component of an owner's
10	 * {@link OwnerIdentity identity key} and to detect a {@link FlagPossibleDuplicate soft-match}
11	 * against an existing owner sharing a sound-alike last name and postcode.
12	 *
13	 * <p>Non-letters are ignored and case is irrelevant. A name with no letters (or {@code null})
14	 * encodes to the empty string.
15	 */
16	final class Soundex {
17	
18	    /** Fixed width of a Soundex code: the retained first letter plus three digits. */
19	    private static final int CODE_LENGTH = 4;
20	
21	    private Soundex() {
22	    }
23	
24	    static String encode(String name) {
25	        if (name == null) {
26	            return "";
27	        }
28	        String letters = lettersOnly(name);
29	        if (letters.isEmpty()) {
30	            return "";
31	        }
32	        StringBuilder code = new StringBuilder(CODE_LENGTH);
33	        code.append(letters.charAt(0));
34	        // The first letter's own code seeds the run so a second letter sharing it is dropped.
35	        char previous = digitOf(letters.charAt(0));
36	        for (int i = 1; i < letters.length() && code.length() < CODE_LENGTH; i++) {
37	            char letter = letters.charAt(i);
38	            char digit = digitOf(letter);
39	            if (digit != '0' && digit != previous) {
40	                code.append(digit);
41	            }
42	            // 'h' and 'w' are transparent: they neither code nor break a run of one sound, so a
43	            // same-coded consonant across them stays merged. A vowel resets the run so a repeated
44	            // sound after it is coded again.
45	            if (letter != 'H' && letter != 'W') {
46	                previous = digit;
47	            }
48	        }
49	        while (code.length() < CODE_LENGTH) {
50	            code.append('0');
51	        }
52	        return code.toString();
53	    }
54	
55	    private static String lettersOnly(String name) {
56	        StringBuilder sb = new StringBuilder(name.length());
57	        for (char c : name.toUpperCase(Locale.ROOT).toCharArray()) {
58	            if (c >= 'A' && c <= 'Z') {
59	                sb.append(c);
60	            }
61	        }
62	        return sb.toString();
63	    }
64	
65	    /** The Soundex digit for an upper-case letter, or {@code '0'} for vowels, 'h', 'w' and 'y'. */
66	    private static char digitOf(char letter) {
67	        switch (letter) {
68	            case 'B': case 'F': case 'P': case 'V':
69	                return '1';
70	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
71	                return '2';
72	            case 'D': case 'T':
73	                return '3';
74	            case 'L':
75	                return '4';
76	            case 'M': case 'N':
77	                return '5';
78	            case 'R':
79	                return '6';
80	            default:
81	                return '0';
82	        }
83	    }
84	}
