10	/**
11	 * Immutable structured audit event for a newly created owner, rendered as a single-line JSON
12	 * object {@code {seq, ownerId, memberId, membershipLevel, event}}.
13	 *
14	 * <p>The event carries the owner's primary identifier, the member id, read in {@link #of} alone.
15	 */
16	public record OwnerCreatedEvent(long seq, int ownerId, String memberId, int membershipLevel,
17	        String event) {
18	
19	    /** The {@code event} discriminator carried by every owner-creation event. */
20	    public static final String OWNER_CREATED = "OWNER_CREATED";
21	
22	    private static final JsonMapper JSON = JsonMapper.builder().build();
23	
24	    /**
25	     * Build the event for {@code owner} (already persisted, so its id is set) at sequence number
26	     * {@code seq}, deriving the effective membership level as at {@code asOf}. The owner's primary
27	     * identifier is read here, in one place.
28	     */
29	    public static OwnerCreatedEvent of(long seq, Owner owner, LocalDate asOf) {
30	        return new OwnerCreatedEvent(seq, owner.getId(), owner.getMemberId(),
31	                MembershipLevels.levelOf(owner, asOf), OWNER_CREATED);
32	    }
33	
34	    /** Render this event as a compact single-line JSON object. */
35	    public String toJson() {
36	        return JSON.writeValueAsString(this);
37	    }
