26	    public void service(@Val Owner owner, OwnerEventSequence sequence) {
27	        LocalDate asOf = LocalDate.now();
28	        int points = MembershipLevels.pointsOf(owner, asOf);
29	        AUDIT.info(
30	                "Owner created: id={} memberId={} registrationDate={} membershipPoints={} membershipLevel={}",
31	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
32	                points, MembershipLevels.levelOf(owner, asOf));
33	        AUDIT.info(OwnerCreatedEvent.of(sequence.next(), owner, asOf).toJson());
34	    }
