package org.springframework.samples.petclinic.util;

import java.util.Map;
import java.util.regex.Pattern;

/**
 * Validates an owner's 4-digit postcode against the postcode range of their city's region.
 * Ranges are keyed by the canonical region resolved via {@link CityRegions}; a city whose
 * region is {@link CityRegions#UNKNOWN} has no range and accepts any well-formed 4-digit
 * postcode.
 */
public final class Postcodes {

    /** A well-formed postcode is exactly four digits. */
    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private Postcodes() {
    }

    /** Whether {@code postcode} is exactly four digits. */
    public static boolean isWellFormed(String postcode) {
        return postcode != null && FOUR_DIGITS.matcher(postcode).matches();
    }

    /**
     * The canonical region whose postcode range contains {@code postcode}, or {@code null} when
     * the postcode is absent, malformed, or falls in no known range.
     */
    public static String regionOf(String postcode) {
        if (!isWellFormed(postcode)) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The region code derived solely from {@code postcode}: the region whose range contains it,
     * or {@link CityRegions#UNKNOWN} when the postcode is absent, malformed or in no known range.
     */
    public static String regionCode(String postcode) {
        String region = regionOf(postcode);
        return region != null ? region : CityRegions.UNKNOWN;
    }

    /**
     * Whether {@code postcode} is valid for {@code city}: it must be four digits and, when the
     * city's region has a known range, fall within it. A city with no known region accepts any
     * four-digit postcode.
     */
    public static boolean isValidForCity(String city, String postcode) {
        if (!isWellFormed(postcode)) {
            return false;
        }
        int[] range = REGION_RANGE.get(CityRegions.localityOf(city));
        if (range == null) {
            return true;
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.util.MemberId;
import org.springframework.samples.petclinic.util.Postcodes;

/**
 * Assigns the owner's member id before it is saved. The id is the region-and-hash identity
 * {@code <REGION><FY><HASH8><CHK>} (see {@link MemberId}): {@code REGION} is the region derived
 * from the owner's postcode, {@code FY} the two-digit fiscal year of the registration date,
 * {@code HASH8} the first eight upper-case hex characters of the SHA-256 digest over the
 * normalized telephone and last name, and {@code CHK} a Luhn check digit over the preceding
 * segments. Should that id collide with an existing owner's, it is
 * {@link MemberId#deduplicate de-duplicated} with a {@code -<n>} suffix so distinct owners always
 * receive distinct ids. Runs after {@link NormalizeOwnerTelephone} has put the telephone in E.164
 * form, {@link BuildOwner} has produced the entity and {@link ResolveRegistrationDate} has set the
 * registration date, so the hash sees the normalized value and the fiscal year is known; mutates
 * the built owner in place.
 */
public class AssignMemberId {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String region = Postcodes.regionCode(owner.getPostcode());
        String memberId = MemberId.of(region, owner.getRegistrationDate(), owner.getTelephone(),
                owner.getLastName());
        owner.setMemberId(MemberId.deduplicate(memberId, existingIds(ownerRepository)));
    }

    private static Set<String> existingIds(OwnerRepository ownerRepository) {
        Set<String> ids = new HashSet<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getMemberId() != null) {
                ids.add(existing.getMemberId());
            }
        }
        return ids;
    }
}

